/*
-- Query: WITH rfm AS (
    SELECT customer_id,
           DATEDIFF('2025-12-31', MAX(order_date)) AS recency_days,
           COUNT(DISTINCT order_id) AS frequency
    FROM fact_sales
    GROUP BY customer_id
),
scored AS (
    SELECT customer_id,
           NTILE(4) OVER (ORDER BY recency_days DESC) AS r_score,
           NTILE(4) OVER (ORDER BY frequency) AS f_score
    FROM rfm
),
labeled AS (
    SELECT customer_id,
           CASE
               WHEN r_score >= 3 AND f_score >= 3 THEN 'Champions'
               WHEN r_score <= 2 AND f_score >= 3 THEN 'At Risk'
               WHEN r_score >= 3 AND f_score <= 2 THEN 'New or Occasional'
               ELSE 'Lost or Sleeping'
           END AS segment
    FROM scored
)
SELECT customer_id, segment FROM labeled ORDER BY customer_id
-- Date: 2026-11-25 10:01
*/
